 useEffect(()=>{const syncFromUrl=()=>{let key="";try{key=decodeURIComponent(window.location.hash.slice(1));}catch{}const match=menus.find(menu=>menu.label===key);setActive(match?match.label:"Dashboard");setNavigationReady(true);};syncFromUrl();window.addEventListener("popstate",syncFromUrl);window.addEventListener("hashchange",syncFromUrl);return()=>{window.removeEventListener("popstate",syncFromUrl);window.removeEventListener("hashchange",syncFromUrl);};},[]);
 const navigateToMenu=(label:string)=>{window.history.pushState(null,"",`#${encodeURIComponent(label)}`);setActive(label);setMobileOpen(false);};const [query,setQuery]=useState("");const [showFilters,setShowFilters]=useState(false);const [regionFilter,setRegionFilter]=useState("Semua wilayah");const [planFilter,setPlanFilter]=useState("Semua paket");const [statusFilter,setStatusFilter]=useState("Semua status");const [subscriptionFilter,setSubscriptionFilter]=useState("Semua status langganan");const [selectedBusiness,setSelectedBusiness]=useState<string[]|null>(null);const [userDirectoryView,setUserDirectoryView]=useState<"platform"|"tenant">("tenant");const [userQuery,setUserQuery]=useState("");const [userStatusFilter,setUserStatusFilter]=useState("Semua status");const [userBusinessFilter,setUserBusinessFilter]=useState("Semua bisnis");const [selectedUser,setSelectedUser]=useState<(typeof demoUsers)[number]|null>(null);const [showUserFilters,setShowUserFilters]=useState(false);const [planQuery,setPlanQuery]=useState("");const [planStatusFilter,setPlanStatusFilter]=useState("Semua status");const [selectedPlan,setSelectedPlan]=useState<(typeof demoPlans)[number]|null>(null);const [planConfigs,setPlanConfigs]=useState(demoPlans);const [planPriceDraft,setPlanPriceDraft]=useState<Record<string,string>>(()=>Object.fromEntries(demoPlans.map(p=>[p.id,String(p.price)])));const [planPeriodDraft,setPlanPeriodDraft]=useState<Record<string,string>>(()=>Object.fromEntries(demoPlans.map(p=>[p.id,p.period])));const [trialConfig,setTrialConfig]=useState({enabled:true,days:14,eligiblePlans:["Basic","Pro"],oncePerBusiness:true,afterTrial:"Masa tenggang 3 hari"});const [planConfigNotice,setPlanConfigNotice]=useState("");const [planConfigHistory,setPlanConfigHistory]=useState<Array<{id:string;type:string;changedAt:string;summary:string;changes:string[]}>>([]);
