const [showNotificationFilters,setShowNotificationFilters]=useState(false);const [selectedNotification,setSelectedNotification]=useState<(typeof demoNotifications)[number]|null>(null);
 useEffect(()=>{try{const saved=window.localStorage.getItem("pos-saas-superadmin-notification-read-v1");if(saved){const parsed=JSON.parse(saved);if(parsed&&typeof parsed==="object"){setNotificationItems(demoNotifications.map(item=>({...item,read:typeof parsed[item.id]==="boolean"?parsed[item.id]:item.read})));}}}catch(error){console.warn("Status baca notifikasi lokal tidak dapat dipulihkan.",error);}},[]);
 const updateNotificationItems=(updater:(items:typeof demoNotifications)=>typeof demoNotifications)=>{setNotificationItems(current=>{const next=updater(current);try{window.localStorage.setItem("pos-saas-superadmin-notification-read-v1",JSON.stringify(Object.fromEntries(next.map(item=>[item.id,item.read]))));}catch(error){console.warn("Status baca notifikasi tidak dapat disimpan.",error);}return next;});};
