  const filteredUsers=useMemo(()=>{const q=userQuery.trim().toLocaleLowerCase("id-ID");return tenantRegistrants.filter(u=>(!q||[u.id,u.name,u.email,u.phone,u.business,u.businessId,u.region,u.status].join(" ").toLocaleLowerCase("id-ID").includes(q))&&(userStatusFilter==="Semua status"||u.status===userStatusFilter)&&(userBusinessFilter==="Semua bisnis"||u.businessId===userBusinessFilter));},[tenantRegistrants,userQuery,userStatusFilter,userBusinessFilter]);
