 const filteredInvoices=useMemo(()=>{const q=invoiceQuery.trim().toLocaleLowerCase("id-ID");return demoInvoices.filter(v=>(!q||[v.id,v.businessId,v.business,v.owner,v.plan,v.period,v.reference,v.method].join(" ").toLocaleLowerCase("id-ID").includes(q))&&(invoiceStatusFilter==="Semua status"||v.status===invoiceStatusFilter));},[invoiceQuery,invoiceStatusFilter]);
