   <div className="business-note"><ShieldCheck size={15}/> Editor harga dan trial di atas hanya menyimpan perubahan sementara pada state halaman browser. Belum ada penyimpanan permanen, penerapan ke tenant, perubahan invoice, validasi server, atau pencatatan audit produksi.</div>
   {selectedPlan&&<div className="modal-backdrop" onClick={()=>setSelectedPlan(null)}><div className="business-modal plan-modal" onClick={e=>e.stopPropagation()}><div className="modal-head"><div><div className="eyebrow">DETAIL PAKET · DEMO</div><h2>{selectedPlan.name}</h2><div className="business-id">{selectedPlan.id}</div><div className="tenant-status-strip"><span className="tag">{selectedPlan.status}</span><span className="plan-chip">{selectedPlan.period}</span></div></div><button className="icon-btn" onClick={()=>setSelectedPlan(null)} aria-label="Tutup detail paket"><X size={17}/></button></div><div className="detail-section"><div className="section-heading"><b>Harga dan periode</b><span>ILUSTRASI</span></div><div className="detail-grid"><div><span>Harga paket</span><b>Rp {selectedPlan.price.toLocaleString("id-ID")}</b></div><div><span>Periode tagihan</span><b>{selectedPlan.period}</b></div><div><span>Masa percobaan</span><b>{selectedPlan.trial}</b></div><div><span>Status paket</span><b>{selectedPlan.status}</b></div></div></div><div className="detail-section"><div className="section-heading"><b>Batas penggunaan</b><span>KUOTA DEMO</span></div><div className="plan-quota modal-quota">{selectedPlan.limits.map(l=><div key={l.label}><span>{l.label}</span><b>{l.value}</b></div>)}</div></div><div className="detail-section"><div className="section-heading"><b>Hak akses fitur</b><span>ILUSTRASI</span></div><div className="plan-feature-list">{selectedPlan.features.map(x=><div key={x}><CheckCircle2 size={14}/>{x}</div>)}</div><p className="demo-disclaimer">Daftar fitur dan batasan ini merupakan contoh tampilan, belum terhubung ke modul entitlement atau pemeriksaan akses server.</p></div><div className="modal-foot"><span className="demo-pill">Data ilustrasi · read only</span><button className="secondary-btn" onClick={()=>setSelectedPlan(null)}>Tutup</button></div></div></div>}
